// TH16 v1.00a Stage 6 boss non-spell.
// Source: st06bs.ecl.txt Boss2 (186-250) + Boss2_at (252-294).
//
// Kept from the source entry: hitbox/hurtbox (Boss() 500/501: 56,56 -> r28; 50,50 -> r25),
// moveLimit(0,128,240,32), the three 60-frame waits, the moveRand(240,9,0.5) /
// Boss2_at (241 rings, one per frame) / moveRand(60,4,1.9) / wait(60) loop, and the
// 2400-frame setInterrupt(0,2400,2400,"BossCard2") window that ends this attack.
//
// Omitted per transcription-policy (phase handover / presentation / rewards), details in
// report.md: previous-card teardown (etCancel/etClear 640, enmDelete, enmMapleEnemy3,
// callSTD(1), killAllAsync, enmKillAll), BossItemPhase drops, score/stat/capture resets,
// spellEnd/funcSet(0)/laserCancel, fog/stars/anm/sound, lifeMarker, and diffF(%F0), which
// nothing in this card reads.

// TH16 type 9 (bullet-types.md: radius 2.40, colors 0-15); source etSprite(0,9,10).
const TH16_KUNAI: int = 496;

const TIME_LIMIT: int = 2524;   // 120 shell buffer + 2400 source window + 4 startup margin
const OPENING_BUFFER: int = 120;
const SOURCE_LIMIT: int = 2400; // setInterrupt(0, 2400, 2400, "BossCard2") timeout window

// Boss2_at 288-289: A += B; B += 0.000175f, B starts at 0.10472f (radians).
// Accumulated in 1/256 BAM so the per-shot float drift is not truncated to whole BAM.
const ANGLE_SCALE: int = 256;
const ROT_STEP0: int = 279621;   // 0.10472 rad  -> 1092.27 BAM
const ROT_STEP_INC: int = 467;   // 0.000175 rad -> 1.825 BAM
const ROT_SHOTS: int = 241;      // $C = 241, then "if ($C--) goto" body count

// Enemy shared slots: int0 = move step k, int1 = active move duration (0 = idle),
// int2 = source clock, fx0/fx1 = cos/sin of the chosen direction, fx2 = start speed.
sub mv_arm() {
    var dur: int = self_int(1);
    if dur > 0 {
        var k: int = self_int(0) + 1;
        set_self_int(0, k);
        var sp: fx = 0fx;
        if k < dur { sp = self_fx(2) * (dur - k) / dur; }
        var nx: fx = $self_x + self_fx(0) * sp;
        var ny: fx = $self_y + self_fx(1) * sp;
        // moveLimit(0,128,240,32): full width/height, so x in [-120,120], y in [112,144].
        if nx < -120fx { nx = -120fx; }
        if nx > 120fx { nx = 120fx; }
        if ny < 112fx { ny = 112fx; }
        if ny > 144fx { ny = 144fx; }
        move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
    }
}

// 412 moveRand: one fixed direction alpha at call time, speed ramping linearly to 0 over
// `dur` ticks (speed mode inherited from source moveVelTime(0,0,0,0)). The direction
// inner region is the limit centre +- width/height quarter: x +-60, y 120..136.
sub mv_rand(dur: int, sp: fx) {
    var r: int = rand(65536) - 32768;   // signed unit random * pi, in BAM
    var a: int = r / 3;
    if $self_x < -60fx {
        a = r / 3;
    } else if $self_x > 60fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 120fx {
        if a < 0 { a = -a; }
    } else if $self_y > 136fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // +-pi/2 guard, epsilon 0.05 rad (nearest BAM bounds).
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    set_self_fx(0, cos(a as angle));
    set_self_fx(1, sin(a as angle));
    set_self_int(0, 0);
    set_self_int(1, dur);
    set_self_fx(2, sp);
    mv_arm();
}

// Every source wait inside this attack advances the source clock and queues the next
// movement tick, so the boss fires from P(k) before phase 5 moves it to P(k+1).
sub att_wait(n: int) {
    for i in 0..n {
        wait(1);
        set_self_int(2, self_int(2) + 1);
        mv_arm();
    }
}

// Boss2_at: one ring per frame for 241 frames. Difficulty values come from the 258-277
// stack pushes: ways E/N/H/L = 1/4/5/6, speed = 2.0/2.0/2.5/3.0.
sub wave() {
    var rank: int = global(GVAR_RANK);
    var ways: int = 1;
    var speed: fx = 2fx;
    var dist: fx = 16fx;
    if rank == 1 { ways = 4; }
    if rank == 2 { ways = 5; speed = 2.5fx; dist = 14fx; }
    if rank == 3 { ways = 6; speed = 3fx; dist = 12fx; }

    // 600-611: etNew(0), aim mode 3 (fixed ring), sprite 9/10, count ways x 1,
    // speed s0 with unused s1 (single layer), then the ANIM record and etDist(24).
    sh_reset(0);
    sh_sprite(0, TH16_KUNAI, 10);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, ways, 1);
    sh_speed(0, speed, 0fx);
    // 627 etDist 24 combined with the 287 ANIM birth offset position -= 4 * velocity.
    sh_dist(0, 24fx - 4fx * speed);

    var a: int = 0;            // base angle, 1/256 BAM
    var b: int = ROT_STEP0;    // per-frame increment, 1/256 BAM
    var n: int = 0;
    while n < ROT_SHOTS {
        if self_int(2) >= SOURCE_LIMIT { return; }
        sh_angle(0, (a / ANGLE_SCALE) as angle, 0deg);
        sh_fire(0);
        a = a + b;
        b = b + ROT_STEP_INC;
        n = n + 1;
        att_wait(1);
    }
}

async sub boss_attack() {
    set_invuln(65535);
    set_hitbox(25fx);
    set_hurtbox(28fx);
    set_self_int(1, 0);
    set_self_int(2, 0);

    // 230-236: 60 + 60 + 60 frames of entry waits (sounds/animation omitted).
    att_wait(60);
    att_wait(60);
    att_wait(60);

    // 242-248: Boss2_1428 / Boss2_1536 loop.
    loop {
        if self_int(2) >= SOURCE_LIMIT { return; }
        mv_rand(240, 0.5fx);   // 243 moveRand(240, 9, 0.5)
        wave();                // 244 @Boss2_at()
        if self_int(2) >= SOURCE_LIMIT { return; }
        mv_rand(60, 1.9fx);    // 245 moveRand(60, 4, 1.9)
        att_wait(60);          // 246
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    // Source entry position: Boss() movePos(0,128) and the moveLimit centre.
    _ = spawn_enemy(0fx, 128fx, 17400, 0, 0, 0, boss_attack);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
